def solve_game(n):
    memo = {}

    def get_moves(current_player, chosen_set, player_sets):
        moves = []
        my_set = player_sets[current_player]
        for x in range(1, n + 1):
            if x not in chosen_set:
                if (x - 1) not in my_set and (x + 1) not in my_set:
                    moves.append(x)
        return moves

    def minimax(current_player, chosen_set, player_sets):
        state = (current_player, tuple(sorted(list(chosen_set))), 
                 tuple(sorted(list(player_sets[0]))), tuple(sorted(list(player_sets[1]))))
        if state in memo:
            return memo[state]

        moves = get_moves(current_player, chosen_set, player_sets)

        if not moves:
            if len(chosen_set) == n:
                return 0  # Draw
            else:
                # Current player loses. Since it's minimax, we need to return something that indicates the result.
                # Let's use: 1 for Alice wins, -1 for Bob wins, 0 for Draw.
                return -1 if current_player == 0 else 1

        # If Alice (0) is moving, she wants to maximize the result (1 > 0 > -1).
        # If Bob (1) is moving, he wants to minimize the result (-1 < 0 < 1).

        if current_player == 0:
            best_val = -2 # Worse than Bob winning
            for move in moves:
                new_chosen_set = chosen_set | {move}
                new_player_sets = list(player_sets)
                new_player_sets[0] = player_sets[0] | {move}
                res = minimax(1, new_chosen_set, tuple(new_player_sets))
                if res > best_val:
                    best_val = res
                if best_val == 1: # Cannot do better than winning
                    break
            memo[state] = best_val
            return best_val
        else:
            best_val = 2 # Worse than Alice winning
            for move in moves:
                new_chosen_set = chosen_set | {move}
                new_player_sets = list(player_sets)
                new_player_sets[1] = player_sets[1] | {move}
                res = minimax(0, new_chosen_set, tuple(new_player_sets))
                if res < best_val:
                    best_val = res
                if best_val == -1: # Cannot do better than winning
                    break
            memo[state] = best_val
            return best_val

    return minimax(0, set(), (set(), set()))

