def solve_game_bitmask(n):
    memo = {}

    def get_moves(current_player, chosen_mask, player_masks):
        moves_mask = (1 << n) - 1
        # Remove chosen
        moves_mask &= ~chosen_mask

        # For current player, remove numbers consecutive to their own
        my_mask = player_masks[current_player]
        # Numbers consecutive to my_mask
        consecutive_to_my_mask = (my_mask << 1) | (my_mask >> 1)
        # But we only care about bits from 0 to n-1
        consecutive_to_my_mask &= (1 << n) - 1

        moves_mask &= ~consecutive_to_my_mask

        # Return a list of move indices
        moves = []
        for i in range(n):
            if (moves_mask >> i) & 1:
                moves.append(i)
        return moves

    def minimax(current_player, chosen_mask, player_masks):
        state = (current_player, chosen_mask, player_masks[0], player_masks[1])
        if state in memo:
            return memo[state]

        moves = get_moves(current_player, chosen_mask, player_masks)

        if not moves:
            if bin(chosen_mask).count('1') == n:
                return 0  # Draw
            else:
                return -1 if current_player == 0 else 1

        if current_player == 0:
            best_val = -2
            for move in moves:
                new_chosen_mask = chosen_mask | (1 << move)
                new_player_masks = (player_masks[0] | (1 << move), player_masks[1])
                res = minimax(1, new_chosen_mask, new_player_masks)
                if res > best_val:
                    best_val = res
                if best_val == 1:
                    break
            memo[state] = best_val
            return best_val
        else:
            best_val = 2
            for move in moves:
                new_chosen_mask = chosen_mask | (1 << move)
                new_player_masks = (player_masks[0], player_masks[1] | (1 << move))
                res = minimax(0, new_chosen_mask, new_player_masks)
                if res < best_val:
                    best_val = res
                if best_val == -1:
                    break
            memo[state] = best_val
            return best_val

    return minimax(0, 0, (0, 0))

